const {Plugin,Notice,MarkdownRenderer,Component,parseYaml}=require('obsidian');
const fs=require('fs'),path=require('path'),os=require('os');
const {pathToFileURL}=require('url');
function prepareDocument(meta){
 const root=document.querySelector('#content');root.querySelectorAll('script,iframe,object,embed').forEach(e=>e.remove());
 const headings=[...root.querySelectorAll('h1,h2,h3')];let counts=[0,0,0],annex=false,references=false;
 for(const node of [...root.children]){if(node.tagName==='H1')references=/BIBLIOGRAFIA/i.test(node.textContent);else if(references&&node.tagName==='P'&&!node.textContent.startsWith('[Substitueix'))node.classList.add('referencia');}
 const toc=document.createElement('nav');toc.className='toc';const title=document.createElement('div');title.className='toc-title';title.textContent='Índex';toc.append(title);const list=document.createElement('ul');toc.append(list);
 headings.forEach((h,i)=>{const level=Number(h.tagName[1]);let text=h.textContent.replace(/\s*\{\.unnumbered\}/g,'').replace(/^\d+(?:\.\d+)*\s+/,'').trim();if(/^ANNEXOS/i.test(text))annex=true;if(!annex){counts[level-1]++;for(let j=level;j<3;j++)counts[j]=0;text=counts.slice(0,level).join('.')+' '+text;}h.textContent=text;h.id='apartat-'+i;h.dataset.memoriaHeading='true';const li=document.createElement('li');li.className='level-'+level;const a=document.createElement('a');a.href='#'+h.id;for(const [cls,value] of [['toc-label',text],['toc-dots',''],['toc-page','']]){const span=document.createElement('span');span.className=cls;span.textContent=value;a.append(span);}li.append(a);list.append(li);});
 const cover=document.createElement('section');cover.className='cover';function add(cls,values){const el=document.createElement('div');el.className=cls;values.filter(Boolean).forEach((v,i)=>{if(i)el.append(document.createElement('br'));el.append(document.createTextNode(String(v)));});cover.append(el);}
 add('cover-centre',[meta.departament,meta.centre]);add('cover-kind',['Memòria del projecte final']);add('cover-title',[meta.titol||'Memòria del projecte']);add('cover-subtitle',[meta.subtitol]);add('cover-details',[meta.estudis,meta.grup,meta.modul,meta.tutor&&'Tutor/a: '+meta.tutor,meta.autor&&'Autor/a: '+meta.autor,meta.curs,[meta.lloc,meta.data].filter(Boolean).join(', ')]);root.prepend(cover,toc);
}
async function paginateDocument(meta){await document.fonts.ready;await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));await window.PagedPolyfill.preview();const pages=[...document.querySelectorAll('.pagedjs_page')];if(!pages.length||!pages[0].querySelector('.cover'))throw new Error('No s’ha pogut identificar la portada.');if(pages.slice(1).some(p=>p.querySelector('.cover')))throw new Error('La portada ocupa més d’una pàgina. Redueix-ne el contingut o la mida al CSS.');const locations={};pages.forEach((p,i)=>{p.querySelectorAll('[data-memoria-heading]').forEach(h=>{if(!(h.id in locations))locations[h.id]=i;});if(i===0)return;p.style.position='relative';const start=!!p.querySelector('h1[data-memoria-heading]');if(start)p.classList.add('inicio-capitol');const footer=document.createElement('div');footer.className='memoria-footer';footer.textContent=String(i);p.append(footer);if(!start){const header=document.createElement('div');header.className='memoria-header '+(i%2?'senar':'parell');header.textContent=i%2?(meta.titol_breu||meta.titol||'Memòria del projecte'):[meta.autor,meta.data].filter(Boolean).join(' · ');p.append(header);}});document.querySelectorAll('.pagedjs_pages .toc a').forEach(a=>{const n=locations[a.getAttribute('href').slice(1)];if(n===undefined)throw new Error('No s’ha trobat un destí de l’índex.');a.querySelector('.toc-page').textContent=String(n);});window.memoriaReady=true;}
module.exports=class extends Plugin{
 onload(){this.addCommand({id:'exportar-memoria',name:'Exportar memòria a PDF',callback:()=>this.export().catch(e=>new Notice('No s’ha exportat: '+e.message,12000))});}
 async export(){if(this.busy)return;this.busy=true;let host,component,win,temp;try{const file=this.app.workspace.getActiveFile();if(!file||file.extension!=='md')throw new Error('Obre una nota Markdown.');const raw=await this.app.vault.read(file);const match=raw.match(/^\uFEFF?---\r?\n([\s\S]*?)\r?\n---\s*\r?\n/);const meta=match?parseYaml(match[1])||{}:{};const body=raw.slice(match?match[0].length:0).replace(/^:::.*$/gm,'').replace(/\s*\{\.unnumbered\}/g,'');const base=this.app.vault.adapter.getBasePath(),dir=path.join(base,this.manifest.dir),css=fs.readFileSync(path.join(path.dirname(path.join(base,file.path)),'memoria-pdf.css'),'utf8'),paged=fs.readFileSync(path.join(dir,'paged.js'),'utf8');host=document.createElement('div');host.style.cssText='position:absolute;left:-20000px;width:155mm;';document.body.append(host);component=new Component();component.load();await MarkdownRenderer.render(this.app,body,host,file.path,component);if(host.querySelector('.mermaid,iframe,video,audio'))throw new Error('Exporta els diagrames Mermaid com a imatges abans d’exportar.');for(const img of host.querySelectorAll('img')){const src=img.getAttribute('src')||'';if(src.startsWith('data:'))continue;const link=img.getAttribute('data-src')||src,target=this.app.metadataCache.getFirstLinkpathDest(decodeURIComponent(link).split('|')[0],file.path);if(!target)throw new Error('No es troba la imatge local: '+link);const mime={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',svg:'image/svg+xml',webp:'image/webp',gif:'image/gif'}[target.extension];if(!mime)throw new Error('Format d’imatge no compatible: '+target.extension);img.src='data:'+mime+';base64,'+Buffer.from(await this.app.vault.readBinary(target)).toString('base64');}host.querySelectorAll('script,iframe,object,embed,link,style').forEach(e=>e.remove());host.querySelectorAll('*').forEach(e=>[...e.attributes].filter(a=>/^on/i.test(a.name)).forEach(a=>e.removeAttribute(a.name)));const safe=JSON.stringify(meta).replace(/</g,'\\u003c'),script=prepareDocument.toString()+'\n'+paginateDocument.toString()+`\nconst meta=${safe};prepareDocument(meta);paginateDocument(meta).catch(e=>window.memoriaError=e.message);`;const html='<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data:; font-src data:; connect-src data:"><style>'+css+'</style><script>window.PagedConfig={auto:false};</script><script>'+paged.replace(/<\/script/gi,'<\\/script')+'</script></head><body><main id="content">'+host.innerHTML+'</main><script>'+script+'</script></body></html>';temp=fs.mkdtempSync(path.join(os.tmpdir(),'memoria-css-'));const input=path.join(temp,'memoria.html');fs.writeFileSync(input,html);const electron=require('electron'),remote=electron.remote||electron;if(!remote.BrowserWindow)throw new Error('El motor d’impressió d’Obsidian no està disponible.');win=new remote.BrowserWindow({show:false,webPreferences:{nodeIntegration:false,contextIsolation:true}});new Notice('Calculant les pàgines i l’índex…');await win.loadURL(pathToFileURL(input).href);const start=Date.now();let ready=false;while(Date.now()-start<90000){const state=await win.webContents.executeJavaScript('({ready:!!window.memoriaReady,error:window.memoriaError})');if(state.error)throw new Error(state.error);if(state.ready){ready=true;break;}await new Promise(r=>setTimeout(r,200));}if(!ready)throw new Error('S’ha superat el temps de paginació. No s’ha substituït el PDF anterior.');const bytes=await win.webContents.printToPDF({printBackground:true,preferCSSPageSize:true,displayHeaderFooter:false});const output=path.dirname(path.join(base,file.path));fs.mkdirSync(output,{recursive:true});fs.writeFileSync(path.join(output,file.basename+'.pdf'),bytes);new Notice('PDF generat: '+file.basename+'.pdf',5000);}finally{if(win)win.destroy();if(component)component.unload();if(host)host.remove();if(temp){try{fs.unlinkSync(path.join(temp,'memoria.html'));fs.rmdirSync(temp);}catch{}}this.busy=false;}}
};
